WHERE s.lambda_version_id = #{lambdaVersionId}
  AND s.request_date > v.function_start_date
  AND i.deleted_at IS NULL
  AND (i.end_date IS NULL OR i.end_date > NOW())
  AND s.request_date >= #{startDate} AND s.request_date < #{endDate}
  AND s.part IN (#{p})
AND s.lane = #{lane}
AND (s.triggers & #{trigger})
AND s.lambda_assignment_id = #{lambdaAssignmentId}
AND s.result_code != 0

mapper.update:
UPDATE lambda_errors
SET error_count = COALESCE(error_count, 0) + 1,
    error_date = COALESCE(error_date, #{functionStartDate})
WHERE lambda_version_id = #{lambdaVersionId}
  AND code_upload_date = #{functionStartDate}
  AND error_signature = #{errorSignature}

UPDATE lambda_errors
SET error_date = #{date}, error_count = 0
WHERE lambda_version_id = #{lambdaVersionId}
  AND code_upload_date = #{functionStartDate}
  AND error_signature = #{errorSignature}
  AND error_date = #{errorDate}

mapper.select:
SELECT error_count, error_date
FROM lambda_errors
WHERE lambda_version_id = #{lambdaVersionId}
  AND code_upload_date = #{functionStartDate}
  AND error_signature = #{errorSignature}

mapper.update:
UPDATE lambda_latest_runs
SET aws_log_end_date = #{logEndDate}
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND invocation_lane = #{lane}

mapper.select:
SELECT aws_log_end_date
FROM lambda_latest_runs
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND invocation_lane = #{lane}

SELECT h.lambda_id AS "lambda_version_lambda_id", h.lambda_version_id, h.lambda_version, h.sequence_number,
       h.created_by, h.created_at, h.whatsnew, h.arch, h.code_upload_id, h.status, h.status_date,
       h.lambda_trigger, h.schedule, v.latest_status, v.is_public,
       v.timeout, v.memory, v.function_start_date, v.function_name, v.async_function_name
FROM lambda_versions h
LEFT OUTER JOIN lambda_active_versions v
    ON v.lambda_id = h.lambda_id AND v.lambda_version_id = h.lambda_version_id
WHERE h.lambda_id = #{lambdaId}
AND h.lambda_version = #{version}

    AND h.status IN (
        #{status}
    )
